/**
 * The font catalogue behind the brand's font picker: every Google Fonts family (lib/fonts/googleFontsData.ts, generated by
 * scripts/generate-google-fonts.mjs), with search, style filters, favourites, recommended pairs and the stylesheet addresses
 * that load a font. Pure: no network, no DOM. The picker loads a font's stylesheet only when it is on screen.
 */
import { GOOGLE_FONTS_DATA } from "./googleFontsData";

export type FontKind = "sans" | "serif" | "display" | "handwriting" | "mono";
export type FontEntry = { name: string; kind: FontKind; /** 1 = the most used font on Google Fonts. */ rank: number; weights: number[]; italic: boolean };

const KIND: Record<string, FontKind> = { s: "sans", f: "serif", d: "display", m: "mono", h: "handwriting" };

/** The filters an owner sees, in plain words. */
export const FONT_KINDS: ReadonlyArray<{ id: FontKind; label: string; hint: string }> = [
  { id: "sans", label: "Clean (sans-serif)", hint: "Simple and modern" },
  { id: "serif", label: "Classic (serif)", hint: "Traditional and trusted" },
  { id: "display", label: "Headline", hint: "Big and full of character" },
  { id: "handwriting", label: "Handwritten", hint: "Personal and warm" },
  { id: "mono", label: "Typewriter (mono)", hint: "Technical and precise" },
];

export const FONTS: FontEntry[] = GOOGLE_FONTS_DATA.map((row, i) => {
  const [name, code, w, it] = row.split("|");
  return { name, kind: KIND[code] ?? "sans", rank: i + 1, weights: [...w].map((d) => Number(d) * 100), italic: it === "i" };
});
const BY_NAME = new Map(FONTS.map((f) => [f.name.toLowerCase(), f] as const));

/** The catalogue entry for a family name (any capitalisation), or undefined (a system font, an uploaded one, a typo). */
export const findFont = (name: string | undefined | null): FontEntry | undefined => (name ? BY_NAME.get(name.trim().toLowerCase()) : undefined);

export const WEIGHT_NAMES: Record<number, string> = { 100: "Thin", 200: "Extra light", 300: "Light", 400: "Regular", 500: "Medium", 600: "Semi-bold", 700: "Bold", 800: "Extra bold", 900: "Black" };

const FALLBACK: Record<FontKind, string> = {
  sans: "ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif",
  display: "ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif",
  serif: "ui-serif, Georgia, Cambria, 'Times New Roman', Times, serif",
  mono: "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Courier New', monospace",
  handwriting: "cursive",
};
/** A CSS font-family value for a name: quoted, with a fallback that suits its style. */
export const cssFamily = (name: string, kind: FontKind = findFont(name)?.kind ?? "sans"): string => `"${name}", ${FALLBACK[kind]}`;

// ---------------------------------------------------------------- finding fonts

export type FontQuery = { query?: string; kind?: FontKind | "all"; /** Only these names (favourites). */ only?: string[]; limit?: number };

/** Fonts matching the search and style, most used first; names that START with the search come before names that merely contain it. */
export function searchFonts(q: FontQuery = {}, pool: FontEntry[] = FONTS): FontEntry[] {
  const needle = (q.query ?? "").trim().toLowerCase();
  const only = q.only ? new Set(q.only.map((n) => n.toLowerCase())) : null;
  const out = pool.filter((f) => (!q.kind || q.kind === "all" || f.kind === q.kind) && (!only || only.has(f.name.toLowerCase())) && (!needle || f.name.toLowerCase().includes(needle)));
  if (needle) out.sort((a, b) => Number(b.name.toLowerCase().startsWith(needle)) - Number(a.name.toLowerCase().startsWith(needle)) || a.rank - b.rank);
  return q.limit ? out.slice(0, q.limit) : out;
}

/** The nearest weight the family really has (a font asked for a weight it lacks makes the whole stylesheet fail). */
export function nearestWeight(name: string, want: number): number {
  const have = findFont(name)?.weights;
  if (!have?.length) return want;
  return have.reduce((best, w) => (Math.abs(w - want) < Math.abs(best - want) ? w : best), have[0]);
}

// ---------------------------------------------------------------- fonts that go well together

export type FontPair = { heading: string; body: string; mood: string };

/** Hand-picked pairs: a heading font and a body font that suit each other. Every name is in the catalogue (a test checks). */
export const FONT_PAIRS: ReadonlyArray<FontPair> = [
  { heading: "Playfair Display", body: "Source Sans 3", mood: "Elegant and readable" },
  { heading: "Montserrat", body: "Merriweather", mood: "Confident and classic" },
  { heading: "Poppins", body: "Inter", mood: "Friendly and modern" },
  { heading: "Plus Jakarta Sans", body: "Inter", mood: "Fresh and clean" },
  { heading: "DM Serif Display", body: "DM Sans", mood: "Warm and stylish" },
  { heading: "Space Grotesk", body: "DM Sans", mood: "Bold and techy" },
  { heading: "Fraunces", body: "Work Sans", mood: "Soft and characterful" },
  { heading: "Oswald", body: "Lora", mood: "Strong and editorial" },
  { heading: "Raleway", body: "Lato", mood: "Light and airy" },
  { heading: "Lora", body: "Nunito Sans", mood: "Gentle and personal" },
  { heading: "Bebas Neue", body: "Open Sans", mood: "Loud and sporty" },
  { heading: "Cormorant Garamond", body: "Montserrat", mood: "Luxurious and calm" },
  { heading: "Manrope", body: "Inter", mood: "Neutral and sharp" },
  { heading: "Libre Baskerville", body: "Roboto", mood: "Trusted and timeless" },
  { heading: "Pacifico", body: "Nunito", mood: "Playful and sunny" },
  { heading: "Merriweather", body: "Open Sans", mood: "Reliable and warm" },
  { heading: "Archivo Black", body: "Work Sans", mood: "Punchy and direct" },
  { heading: "Abril Fatface", body: "Poppins", mood: "Dramatic and chic" },
];

/** Recommended pairs that use this font (as heading or body), best matches first. */
export function pairsFor(name: string): FontPair[] {
  const n = name.trim().toLowerCase();
  return FONT_PAIRS.filter((p) => p.heading.toLowerCase() === n || p.body.toLowerCase() === n);
}

/** A good partner for a font, so choosing one font can fill in the other: a listed pair when there is one, else a sensible rule. */
export function suggestPartner(name: string, role: "heading" | "body"): string | null {
  const hit = pairsFor(name).find((p) => (role === "heading" ? p.heading : p.body).toLowerCase() === name.trim().toLowerCase());
  if (hit) return role === "heading" ? hit.body : hit.heading;
  const f = findFont(name);
  if (!f) return null;
  if (role === "heading") return f.kind === "sans" ? "Lora" : "Inter";
  return f.kind === "serif" ? "Montserrat" : "Playfair Display";
}

// ---------------------------------------------------------------- loading fonts

const enc = (s: string) => encodeURIComponent(s).replace(/%20/g, "+");

/** The Google Fonts stylesheet for a family at the weights asked for (only ones it has), with display=swap so text shows at once. Null for a name that isn't Google's. */
export function fontStylesheetHref(name: string, weights: number[] = [400, 700]): string | null {
  const f = findFont(name);
  if (!f) return null;
  const have = [...new Set(weights.map((w) => nearestWeight(f.name, w)))].sort((a, b) => a - b);
  const axis = f.weights.length === 1 ? "" : `:wght@${have.join(";")}`;
  return `https://fonts.googleapis.com/css2?family=${enc(f.name)}${axis}&display=swap`;
}

/** A tiny stylesheet with just the letters needed to show a font's own name in a list (a few KB). */
export function fontPreviewHref(name: string): string | null {
  const f = findFont(name);
  if (!f) return null;
  const weight = f.weights.includes(400) ? "" : `:wght@${f.weights[0]}`;
  return `https://fonts.googleapis.com/css2?family=${enc(f.name)}${weight}&text=${encodeURIComponent(f.name)}&display=swap`;
}

/** One request for several families at once (the brand sheet's @import): exact weights, display=swap, no family twice. */
export function fontsImportHrefs(requests: Array<{ family: string; weights?: number[] }>): string[] {
  const seen = new Set<string>();
  const parts: string[] = [];
  for (const r of requests) {
    const f = findFont(r.family);
    if (!f || seen.has(f.name)) continue;
    seen.add(f.name);
    const have = [...new Set((r.weights?.length ? r.weights : [400, 700]).map((w) => nearestWeight(f.name, w)))].sort((a, b) => a - b);
    parts.push(f.weights.length === 1 ? `family=${enc(f.name)}` : `family=${enc(f.name)}:wght@${have.join(";")}`);
  }
  // Google's css2 endpoint takes many families, but keep a request to a sensible size.
  const out: string[] = [];
  for (let i = 0; i < parts.length; i += 8) out.push(`https://fonts.googleapis.com/css2?${parts.slice(i, i + 8).join("&")}&display=swap`);
  return out;
}

/** The two tags that let the browser open the font connections early (published pages add them before the brand sheet). */
export const FONT_PRECONNECT_TAGS = `<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>`;
